ALTER TABLE public."DEVICE" ADD COLUMN IF NOT EXISTS "Hostname" text;

CREATE TABLE IF NOT EXISTS public."SCAN_SESSION" (
  "ScanSessionID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TriggerType" text NOT NULL DEFAULT 'manual' CHECK ("TriggerType" IN ('manual', 'scheduled')),
  "TriggeredByUserID" integer REFERENCES public."USERS" ("UserID") ON DELETE SET NULL,
  "Cidr" text,
  "Status" text NOT NULL DEFAULT 'running' CHECK ("Status" IN ('running', 'completed', 'failed')),
  "StartedAt" timestamptz NOT NULL DEFAULT now(),
  "CompletedAt" timestamptz,
  "DevicesFound" integer,
  "NewDevices" integer,
  "ErrorMessage" text
);
CREATE INDEX IF NOT EXISTS idx_scan_session_started ON public."SCAN_SESSION" ("StartedAt" DESC);
ALTER TABLE public."SCAN_SESSION" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."SCAN_SESSION" FROM anon, authenticated;

-- Enable Realtime (WAL change feed) for the tables the dashboard needs pushed updates for.
-- Server-side subscriptions use the secret key (service_role), which bypasses RLS like
-- the rest of this backend already does; RLS itself stays fully locked down as-is.
-- The "supabase_realtime" publication only exists on Supabase-hosted Postgres, so each
-- ALTER PUBLICATION is wrapped to no-op (instead of failing the whole migration) on any
-- other Postgres, e.g. local test databases.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'DEVICE'
  ) THEN
    BEGIN
      ALTER PUBLICATION supabase_realtime ADD TABLE public."DEVICE";
    EXCEPTION WHEN undefined_object THEN
      RAISE NOTICE 'supabase_realtime publication not found; skipping (expected outside Supabase-hosted Postgres)';
    END;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'ALERT'
  ) THEN
    BEGIN
      ALTER PUBLICATION supabase_realtime ADD TABLE public."ALERT";
    EXCEPTION WHEN undefined_object THEN
      RAISE NOTICE 'supabase_realtime publication not found; skipping (expected outside Supabase-hosted Postgres)';
    END;
  END IF;
END $$;
